namespace App\Filament\Imports;

use App\Models\StudentProfile;
use App\Models\Student;
use Filament\Actions\Imports\ImportColumn;
use Filament\Actions\Imports\Importer;
use Filament\Actions\Imports\Models\Import;
use Illuminate\Support\Number;
use Filament\Forms\Components\Checkbox;

/**
 * Generated importer for Student Profile rows from CSV/XLSX.
 */
class StudentProfileImporter extends Importer
{
    protected static ?string $model = StudentProfile::class;

    /**
     * Mappable import columns with type casts and rules.
     * @return  array  ImportColumn definitions.
     */
    public static function getColumns(): array
    {
        return [
            ImportColumn::make('id')
                ->label('ID')
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['integer'])
                ->examples(['1', '2'])
                ->exampleHeader('ID'),

            ImportColumn::make('student')
                ->label('nama_penuh')
                ->requiredMapping()
                ->relationship(resolveUsing: ['nama_penuh'])
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['required', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('nama_penuh'),

            ImportColumn::make('alamat')
                ->label('Address')
                ->ignoreBlankState()
                ->examples(['Sample Address 1', 'Sample Address 2'])
                ->exampleHeader('Address'),

            ImportColumn::make('no_telefon')
                ->label('Phone Number')
                ->ignoreBlankState()
                ->rules(['max:20'])
                ->examples(['Sample Phone Number 1', 'Sample Phone Number 2'])
                ->exampleHeader('Phone Number'),

            ImportColumn::make('tarikh_lahir')
                ->label('Date of Birth')
                ->ignoreBlankState()
                ->rules(['date'])
                ->examples(['2024-01-01', '2024-12-31'])
                ->exampleHeader('Date of Birth'),

            ImportColumn::make('info_kecemasan')
                ->label('Emergency Info')
                ->ignoreBlankState()
                ->rules(['max:200'])
                ->examples(['Sample Emergency Info 1', 'Sample Emergency Info 2'])
                ->exampleHeader('Emergency Info'),

            ImportColumn::make('created_at')
                ->label('Created At')
                ->ignoreBlankState()
                ->rules(['datetime'])
                ->examples(['2024-01-01 22:56:00', '2024-12-31 22:56:00'])
                ->exampleHeader('Created At'),

            ImportColumn::make('updated_at')
                ->label('Updated At')
                ->ignoreBlankState()
                ->rules(['datetime'])
                ->examples(['2024-01-01 22:56:00', '2024-12-31 22:56:00'])
                ->exampleHeader('Updated At'),

            ImportColumn::make('deleted_at')
                ->label('Deleted At')
                ->ignoreBlankState()
                ->rules(['datetime'])
                ->examples(['2024-01-01 22:56:00', '2024-12-31 22:56:00'])
                ->exampleHeader('Deleted At'),
        ];
    }

    /**
     * Resolve which record this imported row maps to (generated custom logic).
     * @return  ?StudentProfile  Resolved record instance.
     */
    public function resolveRecord(): ?StudentProfile
    {
    
        $student = Student::firstWhere('nama_penuh', $this->data['student'] ?? null);

        if (!$student) {
            return null;
        }

        return StudentProfile::firstOrNew([
            'pelajar_id' => $student->id
        ]);
    }

    /**
     * Notification body shown when the import finishes.
     *
     * @param  Import  $import  The completed import job.
     * @return  string  Human-readable completion summary.
     */
    public static function getCompletedNotificationBody(Import $import): string
    {
        $body = 'Your Student Profile import has completed and ' . Number::format($import->successful_rows) . ' ' . str('row')->plural($import->successful_rows) . ' imported.';

        if ($failedRowsCount = $import->getFailedRowsCount()) {
            $body .= ' ' . Number::format($failedRowsCount) . ' ' . str('row')->plural($failedRowsCount) . ' failed to import.';
        }

        return $body;
    }
    
    /**
     * Extra options form shown before importing (dry run / update existing).
     * @return  array  Form component definitions.
     */
    public static function getOptionsFormComponents(): array
    {
        return [
            Checkbox::make('updateExisting')
                ->label('Update existing records'),
        ];
    }

}
